#pragma once
// The file names of the two PS1 discs. The game opens files by record number, never by name; each disc has an index whose record i
// is the path file i had on the build machine ("c:\work\cdrom\map\mapbin\alu_a01f.bin", "c:\movie\title.stv"), 0x40 bytes NUL padded.
// RDE ships the indexes as cdrom.fnd (disc 1) and cdrom2.fnd (disc 2); the built-in copy (disc_names.inc, generated by
// `occ disc-names`) stands in when they are absent. DiscNames turns a logical "cdrom/..." path into the record that holds it, for a
// backend that reads files by record.
#include <string>
#include <string_view>
#include <unordered_map>
#include <vector>

#include "core/types.h"

namespace oc::vfs {

// The folder most records lie under; the built-in table stores their names without it (a stored name with no drive is under it).
inline constexpr std::string_view kDiscWorkRoot = "c:/work/cdrom/";

// An index file's records, normalised: lower case, '\' -> '/', drive prefix kept, "" = a record with no name.
std::vector<std::string> parse_disc_records(ByteSpan index);
// The built-in copy of disc 1's or disc 2's parsed index (disc 2 for any disc >= 2), equal to parse_disc_records of RDE's files.
const std::vector<std::string>& builtin_disc_records(int disc);
// The built-in index in the index file's own layout (0x40-byte NUL padded records, normalised names), for readers of raw index bytes.
Bytes builtin_index_bytes(int disc);
// The cdrom member a record names: "c:/work/cdrom/<member>" -> "<member>", any other "c:/<rest>" -> "<rest>" (the movies:
// "movie/title.stv"); runs of '/' become one ("battle/wepon//ken/hagane.kmd" names "battle/wepon/ken/hagane.kmd"). "" for "".
std::string disc_record_member(std::string_view record);

class DiscNames {
 public:
  // From two parsed indexes (parse_disc_records).
  DiscNames(const std::vector<std::string>& disc1, const std::vector<std::string>& disc2);
  // Over the built-in indexes.
  static const DiscNames& builtin();

  // Record numbers of a file, -1 = not named by that disc's index.
  struct Records {
    // On the disc asked for.
    int disc = -1;
    // On the other disc, for a file the disc in the drive does not have.
    int other = -1;
  };
  // A logical "cdrom/<member>" path (any case, '\' accepted) on disc 1 or 2 (others clamp). A name that several records share (a
  // shared program, battle script, weapon model, the placeholders dummy/dummy.dat and map/mapbin/test.prd) gives the lowest record
  // naming it on that disc; every record naming one path holds the same bytes, so records_of lists the others to fall back on.
  // "cdrom/#record/<n>" (kRecordFolder, decimal, leading zeros allowed) is record n on both discs whatever its name, the way to
  // reach a record the indexes leave unnamed. Paths outside "cdrom/" give no record.
  Records find(std::string_view path, int disc) const;
  // Every record naming the path on that disc, ascending (one record for a "#record/<n>" path); empty when none does.
  std::vector<int> records_of(std::string_view path, int disc) const;
  // Every member either index names, each once: disc 1's in record order, then the names only disc 2 has, in its record order.
  // "#record/<n>" paths are not listed.
  const std::vector<std::string>& members() const { return members_; }

  // The member folder of the by-number paths.
  static constexpr std::string_view kRecordFolder = "#record/";
  // "cdrom/#record/00234" for record 234.
  static std::string record_path(int record);

 private:
  // Member -> the records naming it, ascending, per disc; record count per disc.
  std::unordered_map<std::string, std::vector<int>> named_[2];
  size_t count_[2] = {};
  std::vector<std::string> members_;
};

}  // namespace oc::vfs
